<?php

defined('BASEPATH') or exit('No direct script access allowed');
/** New explicit schedule format; historical425 screen/rows retain their original contract. */
class Company_invoice_recurring extends AdminController
{
    public function index()
    {
        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}require_once APPPATH.'services/CompanyInvoiceRecurring.php';require_once APPPATH.'services/CompanyClients.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$acl=new IssuerResourceAccess($this->db,db_prefix());if(!$acl->can($issuer,$actor,'invoices','view')){show_error('Agenda indisponível.',403);return;}$this->output->set_header('Cache-Control: no-store');$s=new CompanyInvoiceRecurring($this->db,db_prefix());$csrf=$this->session->userdata('company_invoice_schedule_csrf');if(!is_string($csrf)||strlen($csrf)!==64){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_invoice_schedule_csrf',$csrf);}$error=null;$detail=null;$directory=[];$clients=[];$currencies=[];$contacts=[];$can_manage=$acl->can($issuer,$actor,'invoices','create')&&$acl->can($issuer,$actor,'invoices','edit')&&$acl->can($issuer,$actor,'customers','view');$decrypt=function($value){$this->load->library('encryption');return$this->encryption->decrypt($value);};
        try{
            if($this->input->method(true)==='POST'){$token=$this->input->post('company_invoice_schedule_csrf',false);if(!is_string($token)||!hash_equals($csrf,$token)){show_error('Recarregue antes de salvar.',403);return;}if(!$can_manage)throw new DomainException('company_invoice_recurring_denied');$action=$this->input->post('action',false);$id=$this->input->post('schedule_id',false);$key=$this->input->post('request_key',false);if(!is_string($key))throw new DomainException('company_invoice_recurring_invalid');
                if($action==='create'){$invoice=$this->input->post('invoice',false);$send=$this->input->post('send',false)==='1';$config=['unit'=>$this->input->post('unit',false),'interval'=>$this->input->post('interval',false),'custom'=>$this->input->post('custom',false)==='1','cycles'=>$this->input->post('cycles',false),'send'=>$send,'contact_id'=>$send?$this->input->post('contact_id',false):0,'base_url'=>$send?rtrim((string)$this->config->base_url(),'/'):''];if(!is_array($invoice))throw new DomainException('company_invoice_recurring_invalid');$id=$s->create($issuer,$actor,$invoice,$config,$key,$send?$decrypt:null);}
                elseif(in_array($action,['pause','resume','cancel'],true))$s->control($issuer,$actor,$id,$this->input->post('revision',false),$action,$key);
                elseif($action==='run'){$r=$s->document($issuer,$actor,$id);if((int)$r['actor_id']!==$actor)throw new DomainException('company_invoice_recurring_denied');$s->run($issuer,$actor,$id,gmdate('Y-m-d'),$decrypt);}else throw new DomainException('company_invoice_recurring_invalid');CompanyRequestScope::invalidateCaches($this);redirect(CompanyRequestScope::adminUrl($this,'company_invoice_recurring?schedule='.(int)$id),'location',303);return;
            }
            elseif(!in_array($this->input->method(true),['GET','HEAD'],true)){show_error('Método não permitido.',405);return;}
            $id=$this->input->get('schedule',false);if($id!==null)$detail=$s->document($issuer,$actor,$id);$directory=$s->page($issuer,$actor);if($can_manage){$clients=(new CompanyClients($this->db,db_prefix()))->page($issuer,$actor,0,100)['items'];$currencies=(new CompanyInvoices($this->db,db_prefix()))->currencies($issuer,$actor);$contacts=$s->contactOptions($issuer,$actor);}
        }catch(DomainException$e){if(str_contains($e->getMessage(),'denied')){show_error('Agenda indisponível nesta empresa.',403);return;}$this->output->set_status_header(str_contains($e->getMessage(),'stale')||str_contains($e->getMessage(),'conflict')?409:422);$error='Confira a configuração e o estado. Origem ou transporte alterados exigem nova série revisada; o histórico permanece preservado.';}
        catch(Throwable$e){log_message('error','Invoice schedule operation unconfirmed; document and transport values omitted.');$this->output->set_status_header(503);$error='Etapa não confirmada. Uma fatura ou fila pode já estar registrada. Reabra a série e retome a mesma ocorrência; não agende outra para compensar.';}
        $this->load->view('admin/companies/invoice_recurring',['issuer'=>$issuer,'actor'=>$actor,'detail'=>$detail,'directory'=>$directory,'clients'=>$clients,'currencies'=>$currencies,'contacts'=>$contacts,'error'=>$error,'can_manage'=>$can_manage,'company_invoice_schedule_csrf'=>$csrf]);
    }
}
